css:
.fx-crl{width:min(760px,100%)}
.fx-crl .box{height:min(70vh,440px);overflow:auto;border:1px solid var(--border);border-radius:var(--radius);background:var(--surface);position:relative;scroll-behavior:smooth}
.fx-crl .rail{position:sticky;top:0;z-index:3;background:var(--surface);border-bottom:1px solid var(--border);display:flex;align-items:center}
.fx-crl .sc{flex:1;display:flex;gap:.5em;overflow-x:auto;padding:.7em 1em;scrollbar-width:none;-webkit-mask:linear-gradient(90deg,transparent,#000 6%,#000 94%,transparent);mask:linear-gradient(90deg,transparent,#000 6%,#000 94%,transparent)}
.fx-crl .sc::-webkit-scrollbar{display:none}
.fx-crl .sc a{flex:none;padding:.5em 1.1em;border-radius:99px;border:1px solid var(--border);text-decoration:none;color:var(--text);font:600 .88em var(--font-body);transition:all calc(.2s/var(--speed))}
.fx-crl .sc a[aria-current=true]{background:var(--primary);color:var(--on-primary);border-color:var(--primary)}
.fx-crl .ar{flex:none;border:0;background:none;color:var(--text);width:2.4em;height:2.4em;font-size:1.1em;cursor:pointer}
.fx-crl section{padding:1.2em 1.4em;min-height:15em;border-bottom:1px dashed var(--border)}
.fx-crl section h3{margin-bottom:.4em}
@media(prefers-reduced-motion:reduce){.fx-crl .box{scroll-behavior:auto}.fx-crl .sc a{transition:none}}
